    [Fact]
    public void Apu_fire_handle_shows_its_state()
    {
        // The vendor's click writes 1 or 0 to the handle's own var, which the extractor read as a momentary button with no
        // state to show: the panel pressed it blind, and a second press stowed a handle the pilot had just pulled. As a
        // toggle on the pulled-state var, in the engine handles' words, the generic path reads it first.
        Bbs757Control apu = Find("BBS757_FIREHANDLE1_CLICK3");

        Assert.Equal(Bbs757Kinds.Toggle, apu.Kind);
        Assert.False(Bbs757Write.IsMomentary(apu));
        Assert.True(Bbs757Write.HasReadableState(apu));
        Assert.Equal("B757_APUFIRE_SWITCH", apu.StateVar);
        Assert.Equal("0=In|1=Pulled", Spell(apu));
        Assert.Equal(Spell(Find("BBS757_FIREHANDLE1_CLICK")), Spell(apu));
        Assert.Equal(Spell(Find("BBS757_FIREHANDLE1_CLICK2")), Spell(apu));
        Assert.Contains(">L:B757_APUFIRE_SWITCH", apu.Press);   // the vendor's click, replayed

        Assert.Equal(Bbs757WriteOutcome.AtPosition, Bbs757Write.ToPosition(apu, 1, 1).Outcome);
        Bbs757WritePlan pull = Bbs757Write.ToPosition(apu, 0, 1);
        Assert.Equal(Bbs757WriteOutcome.Writes, pull.Outcome);
        Assert.Equal(new[] { apu.Press! }, pull.Calls);
        Assert.Equal(Bbs757WriteOutcome.Refused, Bbs757Write.ToPosition(apu, null, 1).Outcome);   // never pressed unread
    }

    [Fact]
    public void The_fourteen_audio_mic_selects_are_buttons_that_select_one_microphone_and_clear_the_rest()
    {
        // The vendor's click sets this microphone to 1 and the panel's other six to 0, so "Off" could never be picked:
        // a combo of Off and On promised what the control cannot do. A button is pressed and says "pressed".
        string[] channels = { "L", "C", "R", "LM", "RR", "PA", "INT" };
        var nodes = new[] { 1, 2 }
            .SelectMany(panel => channels.Select(ch => $"B757_PED_AUDIO_{panel}_MIC_{ch}_LIGHT"))
            .ToList();

        Assert.Equal(14, nodes.Count);
        foreach (string node in nodes)
        {
            Bbs757Control c = Find(node);
            char panelNo = node["B757_PED_AUDIO_".Length];

            Assert.Equal(Bbs757Kinds.Button, c.Kind);
            Assert.True(Bbs757Write.IsMomentary(c));
            Assert.Equal(node, c.StateVar);
            Assert.Empty(c.Positions);
            Assert.False(Bbs757Write.HasReadableState(c));
            foreach (string ch in channels)
                Assert.Contains($"0 (>L:B757_PED_AUDIO_{panelNo}_MIC_{ch}_LIGHT, bool)", c.Press);
            Assert.EndsWith($"1 (>L:{node}, bool)", c.Press);
            Assert.Null(c.Release);
        }
    }

    // ---- Plan 02, task 3: guarded controls ----

    [Fact]
    public void Guarded_controls_carry_their_guard()
    {
        // The emergency lights switch and the two stab trim cutouts move only while their guard is open. The vendor's click
        // on each is gated on that guard (the extractor writes the gate as an "[if ...]" note in front of the click code,
        // which is not RPN), so the map holds no click code for them: each is a switch on its own L:var that names its
        // guard, the value the guard reads while closed and the value closing the guard writes to the switch. The guard
        // keeps its own row, and the app opens it, writes the position and closes it.
        var expected = new (string Node, string Label, string Section, string Panel, string Positions, string Guard, double CloseSets)[]
        {
            ("B757_OVHD_PASS_OXY_Toggle_Switch_CLICK", "Emergency Lights", "Overhead", "Emergency lights and passenger oxygen",
                "0=OFF|1=ARMED|2=ON", "B757_OVHD_SWITCH_GAURD", 1),
            ("B757_Stab_trim_C_toggle_switch_CLICK", "Stab Trim C Cutout", "Pedestal", "Stabilizer trim",
                "0=NORMAL|1=CUTOUT", "B757_AISLE_STAND_STAB_1_GAURD_SWITCH", 0),
            ("B757_Stab_trim_R_toggle_switch_CLICK", "Stab Trim R Cutout", "Pedestal", "Stabilizer trim",
                "0=NORMAL|1=CUTOUT", "B757_AISLE_STAND_STAB_2_GAURD_SWITCH", 0),
        };

        foreach (var e in expected)
        {
            Bbs757Control c = Find(e.Node);

            Assert.Equal(e.Label, c.Label);
            Assert.Equal(Bbs757Kinds.Switch, c.Kind);
            Assert.Equal((e.Section, e.Panel), (c.Section, c.Panel));
            Assert.Equal(e.Node, c.StateVar);
            Assert.Equal(e.Positions, Spell(c));
            Assert.Null(c.Press);
            Assert.Null(c.Release);
            Assert.Null(c.Cw);
            Assert.Null(c.Ccw);
            Assert.Equal(0, c.HoldMs);
            Assert.Equal(e.Guard, c.Guard);
            Assert.Equal(0.0, c.GuardClosed);
            Assert.Equal(e.CloseSets, c.CloseSets);

            Bbs757Control guard = Find(e.Guard);   // the guard has a row of its own, on the same panel, Closed then Open
            Assert.Equal(Bbs757Kinds.Guard, guard.Kind);
            Assert.Equal((c.Section, c.Panel), (guard.Section, guard.Panel));
            Assert.Equal("0=Closed|1=Open", Spell(guard));
            Assert.False(string.IsNullOrWhiteSpace(guard.StateVar));
        }

        // Those three, and no other control, name a guard.
        Assert.Equal(
            expected.Select(e => e.Node).Order(StringComparer.Ordinal),
            Map.Controls.Where(c => c.Guard != null).Select(c => c.Node).Order(StringComparer.Ordinal));
        Assert.All(Map.Controls.Where(c => c.Guard == null), c =>
        {
            Assert.Null(c.GuardClosed);
            Assert.Null(c.CloseSets);
        });
    }

    [Fact]
    public void Every_guard_a_control_names_is_a_guard_row_of_the_map()
    {
        // The exact list above pins today's three. This holds for whatever control has a Guard, so a guarded control a later
        // plan adds (plan 12's) is covered without a new line there: plan 03's writer finds the guard row by node and
        // presses it as a guard, and a pick on a control whose Guard names no row says "{label} unavailable".
        var guarded = Map.Controls.Where(c => c.Guard != null).ToList();

