    // ---- Plan 02, task 7: the gear lever with its OFF detent and the flap lever ----

    [Fact]
    public void Gear_and_flap_levers_are_on_the_panels()
    {
        // The simulator's gear keys cannot select the OFF detent, and the after-takeoff checklist's "gear UP, then OFF" needs
        // it. BlueBird publishes each lever's state var with its detents and says to write one ("Write a detent position",
        // support.bluebirdsim.com/docs/simvars), so both are switches with no click code of their own: the generic path
        // writes the state var to the picked detent (ruling R7). This only builds the writes; nothing here is sent to a sim.
        Bbs757Control gear = Find("B757_MAIN_Landing_Gear_Y");
        Bbs757Control flaps = Find("BBS757_lever_flaps");

        Assert.Equal(("Gear Lever", "Forward panel", "Landing gear", Bbs757Kinds.Switch, "B757_GEAR_HANDLE_POS"),
            (gear.Label, gear.Section, gear.Panel, gear.Kind, gear.StateVar));
        Assert.Equal(new[] { (0d, "UP"), (0.5, "OFF"), (1d, "DOWN") }, Pairs(gear));
        Assert.Equal(("Flap Lever", "Pedestal", "Control stand", Bbs757Kinds.Switch, "B757_FC_FLAP_LEVER"),
            (flaps.Label, flaps.Section, flaps.Panel, flaps.Kind, flaps.StateVar));
        Assert.Equal(
            new[] { (0d, "UP"), (17d, "1"), (41d, "5"), (67d, "15"), (95d, "20"), (125d, "25"), (150d, "30") },
            Pairs(flaps));
        Assert.All(new[] { gear, flaps }, c =>
        {
            Assert.Null(c.Press);
            Assert.Null(c.Release);
            Assert.Null(c.Cw);
            Assert.Null(c.Ccw);
            Assert.Equal(0, c.HoldMs);
            Assert.Null(c.Guard);
            Assert.False(Bbs757Write.IsMomentary(c));
            Assert.True(Bbs757Write.HasReadableState(c));
        });

        // Their places: the gear lever is the first control of the Landing gear panel (plan 12 task 7: the alternate gear
        // switch, its guard first, and the gear lock override follow it), and the flap lever is the one right after the
        // Parking Brake on the Pedestal's Control stand (plan 12 task 4: the flaps are moved on every flight, ahead of the
        // speedbrake levers).
        Assert.Equal(new[] { "Gear Lever", "Altn Gear Guard", "Altn Gear", "Gear Lock Override" },
            Map.Controls.Where(c => c.Panel == "Landing gear").Select(c => c.Label));
        var stand = Map.Controls.Where(c => c.Panel == "Control stand").Select(c => c.Label).ToList();
        Assert.Equal("Flap Lever", stand[stand.IndexOf("Parking Brake") + 1]);

        IReadOnlyList<string> Writes(Bbs757Control c, double? current, double target)
        {
            Bbs757WritePlan plan = Bbs757Write.ToPosition(c, current, target);
            Assert.Equal(Bbs757WriteOutcome.Writes, plan.Outcome);
            return plan.Calls;
        }

        // One absolute write of the picked detent. The checklist's path: gear UP, then OFF (0.5, a value no gear key sets).
        Assert.Equal(new[] { "0.5 (>L:B757_GEAR_HANDLE_POS)" }, Writes(gear, 0, 0.5));
        Assert.Equal(new[] { "1 (>L:B757_GEAR_HANDLE_POS)" }, Writes(gear, 0.5, 1));
        Assert.Equal(new[] { "0.5 (>L:B757_GEAR_HANDLE_POS)" }, Writes(gear, 0.73, 0.5));   // read between detents: still written
        Assert.Equal(new[] { "41 (>L:B757_FC_FLAP_LEVER)" }, Writes(flaps, 0, 41));         // UP to 5
        Assert.Equal(new[] { "150 (>L:B757_FC_FLAP_LEVER)" }, Writes(flaps, 41, 150));      // 5 to 30
        Assert.Equal(new[] { "17 (>L:B757_FC_FLAP_LEVER)" }, Writes(flaps, 23.5, 17));      // read between detents: still written
        // The same writes under a comma-decimal culture (CI runs under en-US): the OFF detent must stay "0.5", not "0,5".
        foreach (string culture in new[] { "de-DE", "sv-SE" })
        {
            Assert.Equal(new[] { "0.5 (>L:B757_GEAR_HANDLE_POS)" }, TestCulture.Run(culture, () => Writes(gear, 0, 0.5)));
            Assert.Equal(new[] { "0.5 (>L:B757_GEAR_HANDLE_POS)" }, TestCulture.Run(culture, () => Writes(gear, 1, 0.5)));
            Assert.Equal(new[] { "41 (>L:B757_FC_FLAP_LEVER)" }, TestCulture.Run(culture, () => Writes(flaps, 0, 41)));
        }
        // A lever already at its detent is left alone, and a value that is no detent is never picked.
        Assert.Equal(Bbs757WriteOutcome.AtPosition, Bbs757Write.ToPosition(gear, 0.5, 0.5).Outcome);
        Assert.Equal(Bbs757WriteOutcome.AtPosition, Bbs757Write.ToPosition(flaps, 95, 95).Outcome);
        Assert.Equal(Bbs757WriteOutcome.Refused, Bbs757Write.ToPosition(gear, 0, 0.75).Outcome);
        Assert.Equal(Bbs757WriteOutcome.Refused, Bbs757Write.ToPosition(flaps, 0, 20).Outcome);
        Assert.Equal(Bbs757WriteOutcome.Refused, Bbs757Write.ToPosition(gear, null, 0.5).Outcome);   // nothing delivered
    }

    // ---- Plan 12, task 1: the knobs the rules leave out and a combo can drive (the generator's direct_positions) ----

    private static void AssertNoClickCode(Bbs757Control c)
    {
        // A direct_positions row never carries click code: the generic path writes the state var to the picked position.
        Assert.Null(c.Press);
        Assert.Null(c.Release);
        Assert.Null(c.Cw);
        Assert.Null(c.Ccw);
        Assert.Equal(0, c.HoldMs);
        Assert.Null(c.Guard);
        Assert.False(Bbs757Write.IsMomentary(c));
        Assert.True(Bbs757Write.HasReadableState(c));
    }

    private static IReadOnlyList<string> WritesFor(Bbs757Control c, double? current, double target)
    {
        Bbs757WritePlan plan = Bbs757Write.ToPosition(c, current, target);
        Assert.Equal(Bbs757WriteOutcome.Writes, plan.Outcome);
        return plan.Calls;
    }

    [Fact]
    public void Auto_Rate_is_a_switch_on_its_own_var_named_MIN_INDEX_MAX_and_writes_3_5_whatever_the_culture()
    {
        // 3.5 is the knob's load value; BlueBird's code uses its whole number (3: a climb limit of 500 ft/min and a descent
        // limit of 300; 0 is 50 and 30, 13 is 2,000 and 1,200), so INDEX at 3.5 shows the load value as what it acts as. The
        // rules dropped the knob (131 positions of 0.1); curation's direct_positions takes it in (docs/b757/evidence/flight-12.md).
        const string stateVar = "B757_OVHD_AUTORATE_SWITCH";
        Bbs757Control rate = Find("B757_OVHD_AUTORATE_SWITCH");

        Assert.Equal(("Auto Rate", "Overhead", "Pressurization", Bbs757Kinds.Switch, stateVar),
            (rate.Label, rate.Section, rate.Panel, rate.Kind, rate.StateVar));
        Assert.Equal(new[] { (0d, "MIN"), (3.5, "INDEX"), (13d, "MAX") }, Pairs(rate));
        AssertNoClickCode(rate);

        Assert.Equal(new[] { $"3.5 (>L:{stateVar})" }, WritesFor(rate, 0, 3.5));
        Assert.Equal(new[] { $"13 (>L:{stateVar})" }, WritesFor(rate, 3.5, 13));
        Assert.Equal(new[] { $"0 (>L:{stateVar})" }, WritesFor(rate, 3.5, 0));
        Assert.Equal(new[] { $"3.5 (>L:{stateVar})" }, WritesFor(rate, 3.7, 3.5));   // a cockpit click left it between: still written
        // The INDEX write under a comma-decimal culture (CI runs under en-US): "3.5", never "3,5".
        foreach (string culture in new[] { "de-DE", "sv-SE" })
        {
            Assert.Equal(new[] { $"3.5 (>L:{stateVar})" }, TestCulture.Run(culture, () => WritesFor(rate, 13, 3.5)));
            Assert.Equal(new[] { $"3.5 (>L:{stateVar})" }, TestCulture.Run(culture, () => WritesFor(rate, 0, 3.5)));
        }
        // A knob already at its pick is left alone, and a value that is no position is never picked.
        Assert.Equal(Bbs757WriteOutcome.AtPosition, Bbs757Write.ToPosition(rate, 3.5, 3.5).Outcome);
        Assert.Equal(Bbs757WriteOutcome.Refused, Bbs757Write.ToPosition(rate, 0, 4).Outcome);
        Assert.Equal(Bbs757WriteOutcome.Refused, Bbs757Write.ToPosition(rate, null, 3.5).Outcome);   // nothing delivered
    }

    [Theory]
    // Plan 12 task 7: each knob on the panel it is on (the EFIS control panels' PFD and ND knobs, the EICAS control panel's
    // concentric BRT knob, a knob on each CDU's face; docs/b757/evidence/panel-audit-12.md), its label saying what it dims.
    [InlineData("B757_ADI_1_LCD_KNOB", "B757_PFD_1_SCREEN_KNOB", "PFD Brightness", "Captain EFIS")]
    [InlineData("B757_ADI_2_LCD_KNOB", "B757_PFD_2_SCREEN_KNOB", "PFD Brightness", "First officer EFIS")]
    [InlineData("B757_HSI_1_SCREEN_KNOB", "B757_HSI_1_SCREEN_KNOB", "ND Brightness", "Captain EFIS")]
    [InlineData("B757_HSI_2_SCREEN_KNOB", "B757_HSI_2_SCREEN_KNOB", "ND Brightness", "First officer EFIS")]
    [InlineData("B757_EICAS_1_SCREEN_KNOB", "B757_EICAS_1_SCREEN_KNOB", "Upper EICAS Brightness", "EICAS control")]
    [InlineData("B757_EICAS_2_SCREEN_KNOB", "B757_EICAS_2_SCREEN_KNOB", "Lower EICAS Brightness", "EICAS control")]
    [InlineData("B757_FMC_1_SCREEN_KNOB", "B757_FMC_1_SCREEN_KNOB", "Captain CDU", "CDU brightness")]
    [InlineData("B757_FMC_2_SCREEN_KNOB", "B757_FMC_2_SCREEN_KNOB", "First Officer CDU", "CDU brightness")]
    public void Each_display_brightness_knob_writes_the_var_BlueBirds_brightness_code_reads(string node, string stateVar, string label,
        string panel)
    {
        // BlueBird's code sets a display's output to knob / 40 * 1.5, never below 0.1 (measured, flight-12.md): 0 dims the
        // display to its minimum and does not turn it off, so there is no Off. 40 is every knob's load value. The cockpit's
        // mouse stops at 30 (20 on the F/O ADI knob), but the code takes 0-40. The PFD knobs are the ADI knobs: the nodes
        // NAMED B757_PFD_x_SCREEN_KNOB write raster vars nothing reads and have no row.
        Bbs757Control knob = Find(node);

        Assert.Equal((label, "Pedestal", panel, Bbs757Kinds.Switch, stateVar),
            (knob.Label, knob.Section, knob.Panel, knob.Kind, knob.StateVar));
        Assert.Equal(new[] { (0d, "Minimum"), (20d, "Half"), (40d, "Full") }, Pairs(knob));
        Assert.DoesNotContain(knob.Positions, p => p.Label.Contains("Off", StringComparison.OrdinalIgnoreCase));
        AssertNoClickCode(knob);

        Assert.Equal(new[] { $"40 (>L:{stateVar})" }, WritesFor(knob, 0, 40));
        Assert.Equal(new[] { $"0 (>L:{stateVar})" }, WritesFor(knob, 40, 0));
        Assert.Equal(new[] { $"20 (>L:{stateVar})" }, WritesFor(knob, 30, 20));   // where the mouse stops: still written
        Assert.Equal(Bbs757WriteOutcome.AtPosition, Bbs757Write.ToPosition(knob, 40, 40).Outcome);
        Assert.Equal(Bbs757WriteOutcome.Refused, Bbs757Write.ToPosition(knob, 40, 30).Outcome);   // 30 is no position
    }

